public class GcdLcm {

    public static void main(String[] args) {

        int a = 36;
        int b = 24;

        // ছোট সংখ্যাটি পর্যন্ত ঘুরে সবচেয়ে বড় common ভাজক
        int small = (a < b) ? a : b;

        int gcd = 1;
        for (int i = 1; i <= small; i++) {
            if (a % i == 0 && b % i == 0) {
                gcd = i;
            }
        }

        int lcm = (a * b) / gcd;

        System.out.println("GCD: " + gcd);
        System.out.println("LCM: " + lcm);
    }
}

