public class PrimeRange {

    public static void main(String[] args) {

        int start = 1;
        int end = 30;

        System.out.print("Primes: ");

        for (int num = start; num <= end; num++) {

            if (num < 2) {
                continue;           // 1 বা তার নিচে prime নয়
            }

            // 2 থেকে num-1 পর্যন্ত কেউ ভাগ করে কি না
            boolean prime = true;
            for (int i = 2; i < num; i++) {
                if (num % i == 0) {
                    prime = false;
                }
            }

            if (prime) {
                System.out.print(num + " ");
            }
        }
    }
}

